package me.larping.anticheat.commands;
import me.larping.anticheat.LarpingAntiCheat; import org.bukkit.*; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class LacCommand implements CommandExecutor, TabCompleter { private final LarpingAntiCheat p; public LacCommand(LarpingAntiCheat p){this.p=p;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!s.hasPermission("lac.admin")){s.sendMessage("§cNo permission.");return true;} if(a.length==0){s.sendMessage("§c/lac alerts|info|violations|clear|reload|debug|checks");return true;} String sub=a[0].toLowerCase(); if(sub.equals("alerts")){s.sendMessage("§aAlerts are "+(p.getConfig().getBoolean("alerts")?"enabled":"disabled")+".");return true;} if(sub.equals("reload")){p.reloadConfig();s.sendMessage("§aConfiguration reloaded.");return true;} if(sub.equals("checks")){s.sendMessage("§aMovement="+p.getConfig().getBoolean("checks.movement")+" Combat="+p.getConfig().getBoolean("checks.combat")+" Interaction="+p.getConfig().getBoolean("checks.interaction"));return true;} if(sub.equals("enable")||sub.equals("disable")){if(a.length<2){s.sendMessage("§c/lac "+sub+" <movement|combat|interaction>");return true;} String key="checks."+a[1].toLowerCase(); if(!p.getConfig().isSet(key)){s.sendMessage("§cUnknown check group.");return true;} p.getConfig().set(key,sub.equals("enable"));p.saveConfig();s.sendMessage("§a"+a[1]+" "+sub+"d.");return true;} if(a.length<2){s.sendMessage("§cSpecify a player.");return true;} Player t=Bukkit.getPlayerExact(a[1]); if(t==null){s.sendMessage("§cPlayer not found.");return true;} if(sub.equals("clear")){p.violations().clear(t);s.sendMessage("§aViolations cleared.");} else {s.sendMessage("§e"+t.getName()+" §7total VL: §f"+String.format("%.1f",p.violations().total(t))+" §7"+p.violations().get(t));} return true; }
 public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return List.of("alerts","info","violations","clear","reload","debug","checks").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a.length==2)return Bukkit.getOnlinePlayers().stream().map(Player::getName).filter(x->x.toLowerCase().startsWith(a[1].toLowerCase())).toList();return List.of();}}
